import re

_UNITS = {
    1: ["s", "sec", "secs", "second", "seconds"],
    60: ["m", "min", "mins", "minute", "minutes"],
    3600: ["h", "hr", "hrs", "hour", "hours"],
    86400: ["d", "day", "days"],
    604800: ["w", "wk", "wks", "week", "weeks"],
}
UNIT_SECONDS = {name: mult for mult, names in _UNITS.items() for name in names}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_ISO_RE = re.compile(
    rf"^P(?:(?P<w>{_NUM})W)?(?:(?P<d>{_NUM})D)?"
    rf"(?:T(?:(?P<h>{_NUM})H)?(?:(?P<m>{_NUM})M)?(?:(?P<s>{_NUM})S)?)?$",
    re.IGNORECASE,
)
_COMPONENT_RE = re.compile(rf"\s*({_NUM})\s*([a-zA-Z]+)\s*")


def _finish(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    if s[0] in "Pp":
        m = _ISO_RE.match(s)
        if not m or not any(m.groupdict().values()) or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        mult = {"w": 604800, "d": 86400, "h": 3600, "m": 60, "s": 1}
        return _finish(sum(float(v) * mult[k] for k, v in m.groupdict().items() if v))

    # Clock notation
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3) or not all(re.fullmatch(r"\d+(?:\.\d+)?", p) for p in parts):
            raise ValueError(f"invalid clock duration: {text!r}")
        vals = [float(p) for p in parts]
        if len(vals) == 2:
            vals.insert(0, 0.0)
        h, mi, sec = vals
        return _finish(h * 3600 + mi * 60 + sec)

    # Number + unit components
    pos = 0
    total = 0.0
    found = False
    while pos < len(s):
        m = _COMPONENT_RE.match(s, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in UNIT_SECONDS:
            raise ValueError(f"unknown unit {m.group(2)!r}")
        total += float(m.group(1)) * UNIT_SECONDS[unit]
        found = True
        pos = m.end()
    if not found:
        raise ValueError(f"invalid duration: {text!r}")
    return _finish(total)

